'use strict';
function showSupply(){const offer=state.supplyOffer;if(!offer||state.roundPhase!=='supply')return;const odds=AutoItems.tierOdds[Math.min(6,state.stage)];showModal(`<div class="supply-selection"><span class="eyebrow">${P.label(state)} · 안전 보급</span><h2>보급품 2개를 선택하세요</h2><p>서로 다른 슬롯을 선택하면 아이템2개를 받습니다. 제시 목록과 선택은 자동 저장됩니다.</p><p class="hint">확정 시50% 확률로 추가 골드 · 발동 시2G/3G 각각50%</p><div class="supply-odds">${odds.map((n,i)=>`<span>${i+1}티어 ${n}%</span>`).join('')}</div><div class="supply-cards">${offer.options.map((id,index)=>{const def=P.itemById(id),chosen=offer.selected.includes(index);return `<button data-supply-slot="${index}" class="supply-card item-tier-${def.tier} ${chosen?'chosen':''}" aria-pressed="${chosen}"><div class="supply-item-art">${itemIcon(id)}</div><small>${def.tier}티어 · ${id}</small><b>${def.name}</b><span>${def.statsText}</span>${def.effect?`<p>${esc(def.effect).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')}</p>`:''}<em>${chosen?'✓ 선택됨':'선택'}</em></button>`;}).join('')}</div><div class="supply-confirm"><span>${offer.selected.length} / 2개 선택</span><button class="primary" data-confirm-supply ${offer.selected.length!==2?'disabled':''}>선택한 아이템 받기</button></div></div>`);$('closeModal').disabled=false;}
function patchDecisionMarkup(entry){return '<section class="patch-decisions"><h3>요청 외 판단·알림 변경 기록</h3>'+[['사용자 승인한 세부 결정','approvedDecisions'],['Codex 판단으로 추가·조정한 사항','additionalChanges'],['알림·팝업·표시 조건 변경','notificationChanges']].map(([title,key])=>'<h4>'+title+'</h4><ul>'+((entry[key]||[]).length?entry[key].map(note=>'<li>'+esc(note)+'</li>').join(''):'<li>별도 기록 없음</li>')+'</ul>').join('')+'</section>';}
function showPatchNotes(){setRecruitOpen(false);hideItemDetail();selected=null;selectedBattle=null;render();showModal(`<div class="patch-notes"><span class="eyebrow">AUTOCHESS · PROTOTYPE ${AutoPatchNotes.current}</span><h2>패치노트</h2><p>버전별 추가·수정 내역과 현재 규칙을 정리했습니다. 아래 내용을 복사해 ChatGPT 기획 대화에 전달하세요.</p><div class="patch-actions"><button class="primary" id="copyPatchBtn">ChatGPT 전달용 전체 복사</button><button id="downloadPatchBtn">MD 파일 저장</button><span id="patchCopyStatus" role="status"></span></div><section class="current-update"><h3>이번 수정사항 · v${AutoPatchNotes.current}</h3><ul>${AutoPatchNotes.history.at(-1).changes.map(c=>'<li>'+esc(c)+'</li>').join('')}</ul></section>${patchDecisionMarkup(AutoPatchNotes.history.at(-1))}${typeof AutoNoticeAudit!=='undefined'?AutoNoticeAudit.toHTML():''}<details class="current-rules"><summary>현재 적용 규칙 · 미구현 사항</summary><pre>${esc(AutoPatchNotes.currentRules)}</pre></details>${typeof fontLabMarkup==='function'?fontLabMarkup():''}<div class="patch-history">${AutoPatchNotes.history.slice().reverse().map(entry=>`<details ${entry.version===AutoPatchNotes.current?'open':''}><summary><b>v${entry.version}</b> ${entry.title}</summary><ul>${entry.changes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul>${entry.note?`<p class="hint">${esc(entry.note)}</p>`:''}${entry.additionalChanges?patchDecisionMarkup(entry):''}</details>`).join('')}</div><details><summary>전달용 원문 보기</summary><textarea id="patchExport" readonly aria-label="ChatGPT 전달용 패치노트">${esc(AutoPatchNotes.toMarkdown())}</textarea></details></div>`);$('closeModal').disabled=false;$('modal').scrollTop=0;}
function discardSelectedItem(uid){if(P.discardItem(state,uid)){hideItemDetail();save();render();notify('T27','아이템을 버렸습니다. 마지막 삭제는 되돌릴 수 있습니다.');}else notify('T28',AutoNoticePolicy.discardRefusal(state,uid));}
function showDeploymentWarning(){const status=V.deploymentStatus(state);showModal(`<section class="deployment-warning"><span class="eyebrow">전투 시작 전 확인</span><h2>전장에 빈 배치 자리가 있습니다</h2><p>현재 <b>${status.count} / ${status.capacity}명</b> 배치되어 있습니다. ${status.missing}명을 더 배치할 수 있습니다.</p><p>${status.count===0?'아군을 1명 이상 배치해야 전투를 시작할 수 있습니다.':'현재 배치로 전투를 시작할까요, 아니면 다시 배치할까요?'}</p><label class="deployment-remember"><input type="checkbox" id="skipDeploymentWarning"> 이번 원정에서 다시 묻지 않기</label><div class="deployment-actions"><button data-cancel-deployment>다시 세팅하기</button><button class="primary" data-confirm-deployment>이대로 진행</button></div></section>`);}
function showBondMembers(id){
 const bond=D.synergies.find(s=>s.id===id);if(!bond)return;const members=D.roster.filter(t=>D.hasBond(t,bond.name)).sort((a,b)=>a.cost-b.cost||a.id.localeCompare(b.id)),active=members.filter(t=>t.playable).length;
 showModal(`<button data-back-bonds>← 전체 조합</button><h2>${esc(bond.name)} · 캐릭터 ${members.length}명</h2><p>${categoryNames[bond.category]} 조합 · 현재 해금 ${active}명 / 미해금 ${members.length-active}명</p><p class="hint">${esc(bond.concept)} · 준비 단계의 전장 배치를 표시합니다.</p><div class="bond-member-grid">${members.map(t=>`<button class="bond-member-card ${t.playable?'':'member-locked'}" data-inspect="${t.id}" data-from-bond="${esc(id)}"><span class="bond-member-portrait">${costOrb(t.id)}${t.playable?icon(t.id):'<span class="draft-placeholder">'+t.id+'</span>'}</span><span><b>${esc(t.name)}</b><small>${t.cost}G · ${t.id}</small><small>${esc(t.race)} / ${esc(t.job)} / ${esc(t.trait)}</small><em>${!t.playable?'🔒 미해금 · 초안':deployed().some(u=>u.id===t.id)?'전장 배치 중':state.units.some(u=>u.id===t.id)?'대기석 보유':'영입 가능'}</em></span></button>`).join('')}</div>`);$('modal').scrollTop=0;
}
function setupContentUI(){
 let backdropDown=false;const dialog=$('modal'),outside=e=>{const r=dialog.getBoundingClientRect();return e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom);};
 dialog.addEventListener('pointerdown',e=>{backdropDown=e.button===0&&outside(e);});
 dialog.addEventListener('pointercancel',()=>{backdropDown=false;});
 dialog.addEventListener('click',e=>{if(backdropDown&&outside(e))dialog.close();backdropDown=false;});
 document.addEventListener('click',e=>{if(!suppressDragClick()&&!e.composedPath().some(n=>n?.id==='recruitPopover'||n?.id==='openRecruitBtn'))setRecruitOpen(false);});
 $('patchBtn').onclick=showPatchNotes;$('homePatchBtn').onclick=showPatchNotes;
 $('itemTrash').onclick=()=>selectedItem?discardSelectedItem(selectedItem):notify('T29','보관 중인 아이템을 휴지통으로 드래그하거나 아이템 정보에서 버리기를 누르세요.');
 $('undoDiscardBtn').onclick=()=>{if(P.undoDiscard(state)){save();render();notify('T30','마지막으로 버린 아이템을 복원했습니다.');}};
 document.addEventListener('click',e=>{const discard=e.target.closest('[data-discard-item]');if(discard)discardSelectedItem(discard.dataset.discardItem);});
 $('modalContent').addEventListener('click',async e=>{const slot=e.target.closest('[data-supply-slot]');if(slot){if(P.toggleSupply(state,Number(slot.dataset.supplySlot))){save();showSupply();}return;}if(e.target.closest('[data-confirm-supply]')){const result=P.confirmSupply(state);if(result){lastResult=result;save();render();showResult(result);}return;}if(e.target.closest('#copyPatchBtn')){const content=AutoPatchNotes.toMarkdown();try{await navigator.clipboard.writeText(content);$('patchCopyStatus').textContent='복사 완료';}catch{$('patchExport').closest('details').open=true;$('patchExport').focus();$('patchExport').select();$('patchCopyStatus').textContent='원문이 선택되었습니다. Ctrl+C로 복사하세요.';}return;}if(e.target.closest('#downloadPatchBtn')){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([AutoPatchNotes.toMarkdown()],{type:'text/markdown;charset=utf-8'}));a.href=url;a.download='AUTOCHESS_PATCH_NOTES_v'+AutoPatchNotes.current+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
}
